        gplay(self, *[FadeIn(label(t, x, -2.3, 44)) for t, x in zip(("83", "88", "1"), xs)], run_time=0.4)
        at(self, "one hundred seventy-two")
        gplay(self, FadeIn(label("172", -3.1, 1.9, 96)), FadeIn(label("not seen on Nov 8", -3.1, 1.15, 40)), run_time=0.6)
